// Agregador Inteligente de Produtividade FMS SENAI SP
// Processa telemetrias do CLP, pedidos e comandos do Injetor de Estados
let historico = flow.get('fms_prod_history') || {
    totalEntregue: 35,
    metaTurno: 40,
    mediaCicloSegundos: 495, // ~8m 15s
    disponibilidadePercent: 87.2,
    eficienciaPercent: 96.5,
    pecasPadrao: 14,
    pecasPersonalizadas: 21,
    minutosOperando: 297,
    minutosTotais: 360,
    currentState: 'PRODUZINDO',
    clpConectado: true,
    cicloAutomatico: true,
    ultimaPecaConcluida: 'SENAI',
    throughput: [
        { hora: '08:00', real: 0, meta: 0 },
        { hora: '09:00', real: 6, meta: 6 },
        { hora: '10:00', real: 13, meta: 12 },
        { hora: '11:00', real: 18, meta: 18 },
        { hora: '12:00', real: 23, meta: 24 },
        { hora: '13:00', real: 30, meta: 30 },
        { hora: '14:00', real: 35, meta: 36 }
    ],
    estagios: [
        { id: 'torno_l1', nome: '1. Torno: Faceamento & L1', teorico: 90, real: 104, desvio: 15.5 },
        { id: 'torno_l2', nome: '2. Torno: Perfil & L2', teorico: 85, real: 92, desvio: 8.2 },
        { id: 'centro_usina', nome: '3. Centro: Furação & Contorno', teorico: 120, real: 148, desvio: 23.3 },
        { id: 'centro_grava', nome: '4. Centro: Gravação do Nome', teorico: 80, real: 84, desvio: 5.0 },
        { id: 'logistica', nome: '5. Logística: Manipulador & Rampas', teorico: 70, real: 67, desvio: -4.3 }
    ],
    estados: [
        { estado: 'PRODUZINDO', label: 'Peça em Processamento / Linha Ativa', cor: '#10b981', pct: 82.5, min: 297, cod: 1 },
        { estado: 'OCIOSO', label: 'CLP Parado (Sem Pedidos)', cor: '#64748b', pct: 8.9, min: 32, cod: 2 },
        { estado: 'ESTOQUE_BAIXO', label: 'Estoque Baixo (Requisitar Recarga)', cor: '#f59e0b', pct: 4.7, min: 17, cod: 3 },
        { estado: 'EMERGENCIA', label: 'Emergência Acionada', cor: '#ef4444', pct: 2.2, min: 8, cod: 4 },
        { estado: 'FALHA_ROBO', label: 'Falha Comunicação Robô', cor: '#a855f7', pct: 1.7, min: 6, cod: 5 }
    ]
};

let notificacaoParaDisparar = null;

// 1. TRATA COMANDO DO INJETOR DE ESTADOS (Enviado pelo painel de controle)
if (msg.topic === 'fms/injetar_estado') {
    const cmd = msg.payload || {};

    if (cmd.tipo === 'set_estado') {
        historico.currentState = cmd.estado;

        // Ajusta percentuais dos estados na rosca de forma consistente
        const mapaPcts = {
            'PRODUZINDO': [82.5, 8.9, 4.7, 2.2, 1.7],
            'OCIOSO': [55.0, 36.4, 4.7, 2.2, 1.7],
            'ESTOQUE_BAIXO': [60.0, 10.0, 26.1, 2.2, 1.7],
            'EMERGENCIA': [45.0, 10.0, 4.0, 39.3, 1.7],
            'FALHA_ROBO': [50.0, 10.0, 4.0, 2.0, 34.0]
        };
        const pcts = mapaPcts[cmd.estado] || mapaPcts['PRODUZINDO'];
        historico.estados[0].pct = pcts[0];
        historico.estados[1].pct = pcts[1];
        historico.estados[2].pct = pcts[2];
        historico.estados[3].pct = pcts[3];
        historico.estados[4].pct = pcts[4];
        historico.disponibilidadePercent = Number((pcts[0] + (pcts[1] * 0.5)).toFixed(1));
    }

    if (cmd.tipo === 'simular_conclusao') {
        historico.totalEntregue += 1;
        const nomePeca = cmd.nome || 'SENAI';
        historico.ultimaPecaConcluida = nomePeca;
        if (nomePeca === 'SENAI') historico.pecasPadrao += 1;
        else historico.pecasPersonalizadas += 1;

        // Atualiza throughput hora atual
        if (historico.throughput.length > 0) {
            historico.throughput[historico.throughput.length - 1].real = historico.totalEntregue;
        }

        notificacaoParaDisparar = {
            nome: nomePeca,
            timestamp: new Date().toLocaleTimeString('pt-BR')
        };
    }

    if (cmd.tipo === 'reset_metricas') {
        historico.totalEntregue = 0;
        historico.pecasPadrao = 0;
        historico.pecasPersonalizadas = 0;
        historico.throughput.forEach(t => t.real = 0);
    }
}

// 2. DETECÇÃO DE PEÇA PRONTA VINDA DO CLP REAL
if (msg.payload && Array.isArray(msg.payload)) {
    const concluidas = msg.payload.filter(p => p.estado === 'Peça pronta');
    if (concluidas.length > 0) {
        historico.totalEntregue += concluidas.length;
        const ultima = concluidas[concluidas.length - 1];
        historico.ultimaPecaConcluida = ultima.nome || 'SENAI';
        notificacaoParaDisparar = {
            nome: ultima.nome || 'SENAI',
            timestamp: new Date().toLocaleTimeString('pt-BR')
        };
    }
}

// 3. ATUALIZA TELEMETRIAS GERAIS DO CLP
if (msg.payload && msg.payload.clpConectado !== undefined) {
    historico.clpConectado = !!msg.payload.clpConectado;
}
if (msg.payload && msg.payload.cicloAutomatico !== undefined) {
    historico.cicloAutomatico = !!msg.payload.cicloAutomatico;
}

// Salva no contexto de fluxo (persistente)
flow.set('fms_prod_history', historico);

return {
    topic: 'fms/produtividade',
    payload: historico,
    notificacaoPecaPronta: notificacaoParaDisparar
};

